"use client";

import {
  motion,
  useMotionValue,
  useReducedMotion,
  useTransform,
  type MotionStyle,
  type MotionValue,
  type TargetAndTransition,
  type Transition,
} from "motion/react";
import { type ComponentPropsWithoutRef, type PointerEvent, useRef } from "react";

import { cn } from "@/lib/utils";

/** Props for a line whose letters grow heavier as a wave passes. It needs a variable font to move smoothly. */
export type WeightWaveProps = Omit<ComponentPropsWithoutRef<"span">, "children"> & {
  text: string;
  /** `wave` travels across the line by itself. `pointer` puts the crest under the pointer. */
  mode?: "wave" | "pointer";
  /** The resting font weight. */
  minWeight?: number;
  /** The weight at the crest. Each letter's slot is sized for this weight. */
  maxWeight?: number;
  /** How many letters the wave covers at once. */
  spread?: number;
  /** Letters the wave crosses each second, in `wave` mode. */
  speed?: number;
  /** Stops the travelling wave. Pass it from a visible pause control, because the wave loops. */
  paused?: boolean;
};

// The swell rises and falls by the same amount, so the curve is symmetric.
const SWELL_EASE = [0.42, 0, 0.58, 1] as const;
const SETTLE: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
// Seconds of rest between two passes.
const REST = 0.8;
const FAR_AWAY = Number.NEGATIVE_INFINITY;
// The glyph reads its weight from a custom property, so the weight is never an inline style.
const GLYPH = "absolute inset-x-0 top-0 text-center font-(--wave-weight)";

// SAFETY: motion animates CSS custom properties; its target type only lacks the custom keys.
const weightOf = (weight: number | number[]) => ({ "--wave-weight": weight }) as TargetAndTransition;

interface LetterProps {
  char: string;
  index: number;
  count: number;
  mode: "wave" | "pointer";
  minWeight: number;
  maxWeight: number;
  spread: number;
  speed: number;
  paused: boolean;
  pointer: MotionValue<number>;
  centres: { current: number[] };
  reach: { current: number };
  register: (index: number, node: HTMLSpanElement | null) => void;
}

function Letter({ char, index, count, mode, minWeight, maxWeight, spread, speed, paused, pointer, centres, reach, register }: LetterProps) {
  // The nearer the pointer, the heavier the letter. A smooth step keeps the crest round.
  const followed = useTransform(pointer, (x) => {
    const near = Math.max(0, 1 - Math.abs(x - (centres.current[index] ?? 0)) / (reach.current || 1));
    return minWeight + (maxWeight - minWeight) * near * near * (3 - 2 * near);
  });
  const swell = spread / speed;
  const travelling = mode === "wave" && !paused;

  return (
    <span ref={(node) => register(index, node)} className="relative inline-block">
      {/* The invisible copy at the heaviest weight sizes the slot, so the line never reflows. */}
      <span className="invisible font-(--wave-max)">{char}</span>
      {mode === "pointer" ? (
        <motion.span
          // SAFETY: motion writes a motion value into a CSS custom property; MotionStyle only lacks custom keys in its type.
          style={{ "--wave-weight": followed } as MotionStyle}
          // Only the weight changes, and the short ease smooths the pointer's steps and the return to rest.
          className={cn(GLYPH, "motion-safe:transition-all motion-safe:duration-150 motion-safe:ease-out")}
        >
          {char}
        </motion.span>
      ) : (
        <motion.span
          initial={weightOf(minWeight)}
          animate={weightOf(travelling ? [minWeight, maxWeight, minWeight] : minWeight)}
          transition={
            travelling
              ? { duration: swell, ease: SWELL_EASE, delay: index / speed, repeat: Infinity, repeatDelay: count / speed + REST }
              : SETTLE
          }
          className={GLYPH}
        >
          {char}
        </motion.span>
      )}
    </span>
  );
}

/**
 * Shows a line of text where a wave of heavier weight crosses the letters, or
 * follows the pointer. Every letter sits in a slot as wide as its heaviest
 * form, so nothing around it moves. Screen readers get the plain text once,
 * and with reduced motion the line is plain text at its resting weight.
 */
export function WeightWave({
  text,
  mode = "wave",
  minWeight = 400,
  maxWeight = 800,
  spread = 5,
  speed = 14,
  paused = false,
  className,
  onPointerMove,
  onPointerLeave,
  ...spanProps
}: WeightWaveProps) {
  const reduceMotion = useReducedMotion();
  const pointer = useMotionValue(FAR_AWAY);
  const slots = useRef<(HTMLSpanElement | null)[]>([]);
  const centres = useRef<number[]>([]);
  const reach = useRef(1);
  const measured = useRef(false);

  if (reduceMotion) {
    return (
      <span {...spanProps} className={className}>
        {text}
      </span>
    );
  }

  const register = (index: number, node: HTMLSpanElement | null) => {
    slots.current[index] = node;
  };

  // Slots keep their width, so one measurement per hover is enough.
  const measure = () => {
    const boxes = slots.current.filter((node) => node !== null).map((node) => node.getBoundingClientRect());
    centres.current = boxes.map((box) => box.left + box.width / 2);
    const mean = boxes.reduce((sum, box) => sum + box.width, 0) / Math.max(boxes.length, 1);
    reach.current = Math.max(mean * spread, 1);
    measured.current = true;
  };

  const follow = (event: PointerEvent<HTMLSpanElement>) => {
    onPointerMove?.(event);
    // A finger has no hover, so only a mouse or a pen moves the crest.
    if (mode !== "pointer" || event.pointerType === "touch") return;
    if (!measured.current) measure();
    pointer.set(event.clientX);
  };

  const release = (event: PointerEvent<HTMLSpanElement>) => {
    onPointerLeave?.(event);
    measured.current = false;
    pointer.set(FAR_AWAY);
  };

  const words = text.split(/\s+/).filter(Boolean);
  const letterCount = words.reduce((sum, word) => sum + [...word].length, 0);
  let position = 0;

  return (
    <span {...spanProps} className={className} onPointerMove={follow} onPointerLeave={release}>
      <span className="sr-only">{text}</span>
      <motion.span
        aria-hidden="true"
        data-mode={mode}
        data-paused={paused || undefined}
        // SAFETY: a CSS custom property carries the heaviest weight to every slot; MotionStyle only lacks custom keys in its type.
        style={{ "--wave-max": maxWeight } as MotionStyle}
      >
        {words.map((word, wordIndex) => (
          // A word never breaks in the middle, and the space after it is a real break point.
          <span key={`${word}-${wordIndex}`}>
            <span className="inline-block whitespace-nowrap">
              {[...word].map((char) => {
                const index = position++;
                return (
                  <Letter
                    key={index}
                    char={char}
                    index={index}
                    count={letterCount}
                    mode={mode}
                    minWeight={minWeight}
                    maxWeight={maxWeight}
                    spread={spread}
                    speed={speed}
                    paused={paused}
                    pointer={pointer}
                    centres={centres}
                    reach={reach}
                    register={register}
                  />
                );
              })}
            </span>
            {wordIndex < words.length - 1 ? " " : null}
          </span>
        ))}
      </motion.span>
    </span>
  );
}
